/**
 * LOGIN PAGE - Page de connexion PedaClic
 * 
 * Fonctionnalités :
 * - Formulaire email/mot de passe
 * - Validation des champs
 * - Messages d'erreur en français
 * - Redirection après connexion
 * - Liens vers inscription et mot de passe oublié
 * 
 * Design : Cards blanches sur fond gris clair
 */

import React, { useState, FormEvent } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useAuth } from '../../hooks/useAuth';
import '../styles/auth.css';

/**
 * Interface pour l'état du formulaire
 */
interface FormState {
  email: string;
  password: string;
}

/**
 * Interface pour l'état de la location (redirection)
 */
interface LocationState {
  from?: string;
}

/**
 * Composant LoginPage
 */
const LoginPage: React.FC = () => {
  // ==================== HOOKS ====================
  const { login, loginWithGoogle } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  
  // Récupérer l'URL de redirection (état ou paramètre ?redirect=)
  const redirectParam = new URLSearchParams(location.search).get('redirect');
  const from = (location.state as LocationState)?.from || redirectParam || '/';

  // ==================== ÉTATS ====================
  
  // État du formulaire
  const [formData, setFormData] = useState<FormState>({
    email: '',
    password: ''
  });
  
  // État de chargement
  const [isLoading, setIsLoading] = useState<boolean>(false);
  
  // État chargement Google
  const [isGoogleLoading, setIsGoogleLoading] = useState<boolean>(false);

  // État d'erreur
  const [error, setError] = useState<string>('');
  
  // Afficher/masquer le mot de passe
  const [showPassword, setShowPassword] = useState<boolean>(false);

  // ==================== HANDLERS ====================

  /**
   * Gère les changements dans les champs du formulaire
   */
  const handleChange = (e: React.ChangeEvent<HTMLInputElement>): void => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Effacer l'erreur quand l'utilisateur modifie un champ
    if (error) setError('');
  };

  /**
   * Valide le formulaire avant soumission
   */
  const validateForm = (): boolean => {
    if (!formData.email.trim()) {
      setError('Veuillez entrer votre adresse email.');
      return false;
    }
    
    if (!formData.password) {
      setError('Veuillez entrer votre mot de passe.');
      return false;
    }
    
    // Validation email simple
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(formData.email)) {
      setError('Veuillez entrer une adresse email valide.');
      return false;
    }
    
    return true;
  };

  /**
   * Gère la soumission du formulaire
   */
  const handleSubmit = async (e: FormEvent<HTMLFormElement>): Promise<void> => {
    e.preventDefault();
    
    // Validation
    if (!validateForm()) return;
    
    setIsLoading(true);
    setError('');

    try {
      await login(formData.email, formData.password);
      // Rediriger vers la page d'origine ou l'accueil
      navigate(from, { replace: true });
    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('Une erreur est survenue lors de la connexion.');
      }
    } finally {
      setIsLoading(false);
    }
  };

  /**
   * Connexion via Google
   */
  const handleGoogleLogin = async (): Promise<void> => {
    setIsGoogleLoading(true);
    setError('');
    try {
      await loginWithGoogle();
      navigate(from, { replace: true });
    } catch (err) {
      if (err instanceof Error) setError(err.message);
    } finally {
      setIsGoogleLoading(false);
    }
  };

  // ==================== RENDU ====================

  return (
    // <!-- Page de connexion - Fond gris clair -->
    <div className="auth-page">
      <div className="auth-container">
        
        {/* <!-- Card de connexion --> */}
        <div className="auth-card">
          
          {/* <!-- En-tête avec logo --> */}
          <div className="auth-header">
            <Link to="/" className="auth-logo">
              <div className="auth-logo__icon">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <path d="M12 6.042A8.967 8.967 0 006 3.75c-1.052 0-2.062.18-3 .512v14.25A8.987 8.987 0 016 18c2.305 0 4.408.867 6 2.292m0-14.25a8.966 8.966 0 016-2.292c1.052 0 2.062.18 3 .512v14.25A8.987 8.987 0 0018 18a8.967 8.967 0 00-6 2.292m0-14.25v14.25"/>
                </svg>
              </div>
              <span>PedaClic</span>
            </Link>
            <h1 className="auth-title">Connexion</h1>
            <p className="auth-subtitle">
              Accédez à votre espace d'apprentissage
            </p>
          </div>

          {/* <!-- Message d'erreur --> */}
          {error && (
            <div className={`auth-error ${error.includes('Vérifiez votre adresse email') ? 'auth-error--verification' : ''}`}>
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                <circle cx="12" cy="12" r="10"/>
                <path d="M12 8v4M12 16h.01"/>
              </svg>
              <div>
                <span>{error}</span>
                {error.includes('Vérifiez votre adresse email') && (
                  <Link
                    to={`/verification-email${formData.email ? `?email=${encodeURIComponent(formData.email)}` : ''}`}
                    className="auth-forgot-link"
                    style={{ display: 'block', marginTop: '0.5rem' }}
                  >
                    Consulter les instructions de vérification →
                  </Link>
                )}
              </div>
            </div>
          )}

          {/* <!-- Formulaire --> */}
          <form onSubmit={handleSubmit} className="auth-form">
            
            {/* <!-- Champ Email --> */}
            <div className="auth-field">
              <label htmlFor="email" className="auth-label">
                Adresse email
              </label>
              <div className="auth-input-wrapper">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" className="auth-input-icon">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 8l7.89 5.26a2 2 0 002.22 0L21 8M5 19h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z"/>
                </svg>
                <input
                  type="email"
                  id="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  placeholder="exemple@email.com"
                  className="auth-input"
                  autoComplete="email"
                  disabled={isLoading}
                />
              </div>
            </div>

            {/* <!-- Champ Mot de passe --> */}
            <div className="auth-field">
              <label htmlFor="password" className="auth-label">
                Mot de passe
              </label>
              <div className="auth-input-wrapper">
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" className="auth-input-icon">
                  <rect x="3" y="11" width="18" height="11" rx="2" ry="2" strokeWidth="2"/>
                  <path strokeWidth="2" d="M7 11V7a5 5 0 0110 0v4"/>
                </svg>
                <input
                  type={showPassword ? 'text' : 'password'}
                  id="password"
                  name="password"
                  value={formData.password}
                  onChange={handleChange}
                  placeholder="Votre mot de passe"
                  className="auth-input"
                  autoComplete="current-password"
                  disabled={isLoading}
                />
                {/* Bouton afficher/masquer */}
                <button
                  type="button"
                  className="auth-password-toggle"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label={showPassword ? 'Masquer le mot de passe' : 'Afficher le mot de passe'}
                >
                  {showPassword ? (
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13.875 18.825A10.05 10.05 0 0112 19c-4.478 0-8.268-2.943-9.543-7a9.97 9.97 0 011.563-3.029m5.858.908a3 3 0 114.243 4.243M9.878 9.878l4.242 4.242M9.88 9.88l-3.29-3.29m7.532 7.532l3.29 3.29M3 3l3.59 3.59m0 0A9.953 9.953 0 0112 5c4.478 0 8.268 2.943 9.543 7a10.025 10.025 0 01-4.132 5.411m0 0L21 21"/>
                    </svg>
                  ) : (
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 12a3 3 0 11-6 0 3 3 0 016 0z"/>
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z"/>
                    </svg>
                  )}
                </button>
              </div>
            </div>

            {/* <!-- Lien mot de passe oublié --> */}
            <div className="auth-forgot">
              <Link to="/mot-de-passe-oublie" className="auth-forgot-link">
                Mot de passe oublié ?
              </Link>
            </div>

            {/* <!-- Bouton de connexion --> */}
            <button
              type="submit"
              className="auth-button"
              disabled={isLoading}
            >
              {isLoading ? (
                <>
                  <span className="auth-button-spinner"></span>
                  Connexion en cours...
                </>
              ) : (
                'Se connecter'
              )}
            </button>
          </form>

          {/* <!-- Séparateur --> */}
          <div className="auth-divider">
            <span>ou</span>
          </div>

          {/* <!-- Bouton Google --> */}
          <button
            type="button"
            className="auth-google-btn"
            onClick={handleGoogleLogin}
            disabled={isLoading || isGoogleLoading}
          >
            {isGoogleLoading ? (
              <>
                <span className="auth-button-spinner auth-button-spinner--dark"></span>
                Connexion en cours…
              </>
            ) : (
              <>
                <svg className="auth-google-icon" viewBox="0 0 24 24" aria-hidden="true">
                  <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                  <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                  <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z"/>
                  <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                </svg>
                Continuer avec Google
              </>
            )}
          </button>

          {/* <!-- Lien vers inscription --> */}
          <p className="auth-switch">
            Pas encore de compte ?{' '}
            <Link to="/inscription" className="auth-switch-link">
              Créer un compte
            </Link>
          </p>
        </div>

        {/* <!-- Message de bienvenue --> */}
        <div className="auth-welcome">
          <h2>Bienvenue sur PedaClic !</h2>
          <p>L'école en un clic - Accédez à des milliers de cours, exercices et quiz.</p>
          <ul className="auth-features">
            <li>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
              </svg>
              Cours du programme sénégalais
            </li>
            <li>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
              </svg>
              Exercices interactifs
            </li>
            <li>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
              </svg>
              Quiz pour tester vos connaissances
            </li>
            <li>
              <svg viewBox="0 0 24 24" fill="currentColor">
                <path d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z"/>
              </svg>
              Suivi de progression
            </li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
