/**
 * Leçons marquées « signet d'évaluation » d'un cahier — VUE ÉLÈVE.
 *
 * Renvoie toutes les entrées du cahier dont `isMarqueEvaluation === true`,
 * indépendamment du statut (une évaluation peut porter sur une séance déjà
 * réalisée comme sur une séance planifiée). Permet d'afficher aux élèves
 * la liste des leçons à réviser avec la date d'évaluation prévue.
 *
 * Robustesse :
 *  - Deux filtres d'égalité sans `orderBy` → pas d'index composite requis.
 *  - En cas d'échec (règles Firestore restreignant la lecture aux séances
 *    réalisées, ou autre), on retombe proprement sur les séances réalisées
 *    déjà lisibles par l'élève et on filtre les signets côté client.
 */
export async function getEntreesEvaluationCahier(cahierId: string): Promise<EntreeCahier[]> {
  try {
    const q = query(
      collection(db, COL_ENTREES),
      where('cahierId', '==', cahierId),
      where('isMarqueEvaluation', '==', true),
    );
    const snap = await getDocs(q);
    return snap.docs.map(d => ({ id: d.id, ...d.data() } as EntreeCahier));
  } catch (err) {
    console.warn('getEntreesEvaluationCahier — repli sur séances réalisées :', err);
    const realisees = await getEntreesRealisees(cahierId);
    return realisees.filter((e) => e.isMarqueEvaluation);
  }
}

export async function createEntree(
  cahierId: string,
  profId: string,
  form: import('../types/cahierTextes.types').EntreeFormData
): Promise<string>;
export async function createEntree(
  data: Omit<EntreeCahier, 'id' | 'createdAt' | 'updatedAt'>
): Promise<string>;
export async function createEntree(
  cahierIdOrData: string | Omit<EntreeCahier, 'id' | 'createdAt' | 'updatedAt'>,
  profId?: string,
  form?: import('../types/cahierTextes.types').EntreeFormData
): Promise<string> {
  const now = Timestamp.now();
  let payload: Record<string, unknown>;

  if (typeof cahierIdOrData === 'string') {
    // Signature Phase 21 : createEntree(cahierId, profId, form)
    const f = form!;
    payload = {
      cahierId:             cahierIdOrData,
      profId:               profId!,
      date:                 Timestamp.fromDate(new Date(f.date)),
      heureDebut:           f.heureDebut || '',
      heureFin:             f.heureFin || '',
      chapitre:             f.chapitre,
      typeContenu:          f.typeContenu,
      contenu:              f.contenu,
      objectifs:            f.objectifs || '',
      competences:          f.competences || [],
      rubrique:             f.rubrique || '',
      statut:               f.statut,
      motifAnnulation:      f.motifAnnulation || '',
      dateReport:           f.dateReport ? Timestamp.fromDate(new Date(f.dateReport)) : null,
      // Heure de report (string "HH:mm") — persistée comme heureDebut/heureFin
      heureReport:          f.heureReport || '',
      notesPrivees:         f.notesPrivees || '',
      isMarqueEvaluation:   Boolean(f.isMarqueEvaluation),
      typeEvaluation:       f.typeEvaluation || null,
      dateEvaluationPrevue: f.dateEvaluationPrevue
        ? Timestamp.fromDate(new Date(f.dateEvaluationPrevue))
        : null,
      statutEvaluation:     f.statutEvaluation,
      ordre:                Date.now(),
      piecesJointes:        [],
      liens:                [],
      ebooksLies:           [],
      contenuIA:            [],
      // Phase 34 — Exercices liés à la leçon (optionnels, persistés en clair)
      exerciceJour:         f.exerciceJour || '',
      exerciceDomicile:     f.exerciceDomicile || '',
      // Phase 35 — Échéance (date + heure) de l'exercice à domicile (null si aucune)
      echeanceDomicile:     f.echeanceDomicile && f.echeanceDomicile.date ? f.echeanceDomicile : null,
    };
  } else {
    // Signature Phase 22 : createEntree(data)
    payload = {
      liens:         [],
      ebooksLies:    [],
      piecesJointes: [],
      contenuIA:     [],
      ...cahierIdOrData,
    };
  }

  const ref = await addDoc(collection(db, COL_ENTREES), {
    ...payload,
    createdAt: now,
    updatedAt: now,
  });
  return ref.id;
}

export async function updateEntree(
  entreeId: string,
  cahierIdOrData: string | Partial<Omit<EntreeCahier, 'id' | 'createdAt'>>,
  form?: import('../types/cahierTextes.types').EntreeFormData
): Promise<void> {
  let payload: Record<string, unknown>;

  if (typeof cahierIdOrData === 'string' && form) {
    // Signature Phase 21 : updateEntree(entreeId, cahierId, form)
    const f = form;
    payload = {
      date:                 Timestamp.fromDate(new Date(f.date)),
      heureDebut:           f.heureDebut || '',
      heureFin:             f.heureFin || '',
      chapitre:             f.chapitre,
      typeContenu:          f.typeContenu,
      contenu:              f.contenu,
      objectifs:            f.objectifs || '',
      competences:          f.competences || [],
      rubrique:             f.rubrique || '',
      statut:               f.statut,
      motifAnnulation:      f.motifAnnulation || '',
      dateReport:           f.dateReport ? Timestamp.fromDate(new Date(f.dateReport)) : null,
      // Heure de report (string "HH:mm") — persistée même vide pour permettre la suppression
      heureReport:          f.heureReport || '',
      notesPrivees:         f.notesPrivees || '',
      isMarqueEvaluation:   Boolean(f.isMarqueEvaluation),
      typeEvaluation:       f.typeEvaluation || null,
      dateEvaluationPrevue: f.dateEvaluationPrevue
        ? Timestamp.fromDate(new Date(f.dateEvaluationPrevue))
        : null,
      statutEvaluation:     f.statutEvaluation,
      // Phase 34 — Exercices liés à la leçon (persistés même s'ils sont vides pour permettre la suppression)
      exerciceJour:         f.exerciceJour || '',
      exerciceDomicile:     f.exerciceDomicile || '',
      // Phase 35 — Échéance (date + heure) de l'exercice à domicile (null pour supprimer)
      echeanceDomicile:     f.echeanceDomicile && f.echeanceDomicile.date ? f.echeanceDomicile : null,
    };
  } else {
    // Signature Phase 22 : updateEntree(entreeId, data)
    payload = { ...cahierIdOrData as object };
  }

  await updateDoc(doc(db, COL_ENTREES, entreeId), {
    ...payload,
    updatedAt: Timestamp.now(),
  });
}

